'use strict';
const $=id=>document.getElementById(id),colors=['#ff6c78','#82e2a7','#6ca8ff'],fmt=n=>n.toLocaleString();
let db=null,nextId=1,selected=null,frame=0,playing=true,lastTick=0,elapsed=0,hold=0,runActive=false,paused=false,busy=false,current=null,checkpoint=null,config=null,sessionDone=0,sessionShown=0,sessionSkipped=0,sessionLimit=Infinity,token=0,page=0,viewSerial=0,toastTimer;
const canvas=$('universe');
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',6000);}
function draw(c,r,idx,small=false){let g=c.getContext('2d'),w=c.width,h=c.height;g.fillStyle='#080d13';g.fillRect(0,0,w,h);let size=Math.min(w,h)*.82,ox=(w-size)/2,oy=(h-size)/2,xy=(x,y)=>[ox+(x+6)*size/12,oy+(6-y)*size/12];g.lineWidth=1;for(let v=-6;v<=6;v++){let [x,y]=xy(v,v);g.strokeStyle=v===0?'#23303e':'#121e2a';g.beginPath();g.moveTo(x,oy);g.lineTo(x,oy+size);g.stroke();g.beginPath();g.moveTo(ox,y);g.lineTo(ox+size,y);g.stroke();}g.strokeStyle='#334150';g.strokeRect(ox,oy,size,size);if(!small){g.font=`${Math.max(10,w/90)}px monospace`;g.fillStyle='#63778a';for(let v=-6;v<=6;v+=2){let [x,y]=xy(v,v);g.fillText(String(v),x-5,oy+size+16);g.fillText(String(v),ox-24,y+4);}}if(!r?.frames?.length)return;idx=Math.max(0,Math.min(Math.floor(idx),r.frames.length-1));g.save();g.beginPath();g.rect(ox,oy,size,size);g.clip();for(let b=0;b<3;b++){g.strokeStyle=colors[b];g.globalAlpha=.7;g.lineWidth=small?1.2:Math.max(1.5,w/550);g.beginPath();for(let i=0;i<=idx;i++){let p=xy(r.frames[i][1+b*2],r.frames[i][2+b*2]);i?g.lineTo(...p):g.moveTo(...p);}g.stroke();let f=r.frames[idx],p=xy(f[1+b*2],f[2+b*2]),radius=(r.initial.scan?.radius||.12)*size/12;g.globalAlpha=1;g.shadowBlur=small?4:12;g.shadowColor=colors[b];g.fillStyle=colors[b];g.beginPath();g.arc(...p,small?Math.max(2,radius):Math.max(3,radius),0,Math.PI*2);g.fill();g.shadowBlur=0;g.strokeStyle='#0d1218';g.lineWidth=1;g.stroke();if(!small){g.font=`${Math.max(10,w/80)}px monospace`;g.fillText(String(b+1).padStart(2,'0'),p[0]+radius+6,p[1]-radius-4);}}g.restore();}
function render(){let b=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2),w=Math.round(b.width*d),h=Math.round(b.height*d);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}draw(canvas,selected,frame);if(selected){let f=selected.frames[Math.min(Math.floor(frame),selected.frames.length-1)];$('clock').innerHTML=f[0].toFixed(3)+' <small>s</small>';$('scrub').value=Math.floor(frame);}}
function thumb(r){let c=document.createElement('canvas');c.width=216;c.height=150;draw(c,r,r.frames.length-1,true);return c.toDataURL('image/png');}
function select(r,autoplay=true){selected=r;frame=0;elapsed=0;hold=0;playing=autoplay;$('play').textContent=playing?'Ⅱ':'▶';$('scrub').max=r.frames.length-1;let scan=r.initial.scan;$('viewLabel').textContent=scan?`TRIAL ${fmt(scan.ordinal+1)} / ${fmt(scan.total)} · CELLS ${scan.triple.map(n=>n+1).join(' / ')}`:`RECORDED TEST ${r.id||'PREVIEW'}`;$('outcomeBadge').textContent=runActive?'STARTS AT REST':(r.outcome||'PREVIEW').toUpperCase();render();}
function badge(){if(!selected)return;$('outcomeBadge').textContent=frame<1?'ALL THREE AT REST':frame<selected.frames.length-1?'MUTUAL GRAVITY':(selected.outcome||'PREVIEW').toUpperCase();$('outcomeBadge').style.color=selected.outcome==='Orbit candidate'&&frame>=selected.frames.length-1?colors[1]:selected.outcome==='Escaped'&&frame>=selected.frames.length-1?colors[0]:'#c6d1db';}
function animate(t){let delta=lastTick?Math.min((t-lastTick)/1000,.2):0;lastTick=t;if(playing&&selected&&!(runActive&&paused&&selected===current)){let length=Math.max(Number($('minimum').value)||4,selected.time/Number($('speed').value));elapsed+=delta;if(elapsed<.8)frame=0;else{let portion=Math.min(1,(elapsed-.8)/length);frame=portion*(selected.frames.length-1);if(portion===1){if(elapsed>=length+1.6){if(runActive&&selected===current&&!busy){playing=false;completeTrial();}else if(!runActive){elapsed=0;frame=0;}}}}badge();render();}requestAnimationFrame(animate);}
function req(q){return new Promise((resolve,reject)=>{q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
function txDone(tx){return new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Storage transaction failed'));});}
async function storeRecord(r){if(!db)throw Error('Browser database is unavailable.');if(r.trialKey){let existing=await req(db.transaction('records').objectStore('records').index('trialKey').getKey(r.trialKey));if(existing!==undefined)r.id=existing;}if(!r.id)r.id=nextId++;r.displayEligible=Number(ReplayFilter.qualifies(r));r.created=r.created||new Date().toISOString();r.finalImage=r.finalImage||thumb(r);let tx=db.transaction('records','readwrite');tx.objectStore('records').put(r);await txDone(tx);await update();}
function checkpointSave(){try{localStorage.setItem('three-body-radius-scan-v2',JSON.stringify(checkpoint));}catch{throw Error('Could not save scan position. Export records before continuing.');}showCheckpoint();}
function showCheckpoint(){if(!checkpoint)return;$('checkpoint').textContent=`Saved next trial: ${fmt(checkpoint.ordinal+1)} of ${fmt(Scan.spec(checkpoint.config.radius).total)} · ${checkpoint.config.radius} m step.`;}
function settings(){return {radius:Number($('radius').value),duration:Number($('duration').value),dt:Number($('dt').value)};}
function same(a,b){return a&&a.radius===b.radius&&a.duration===b.duration&&a.dt===b.dt;}
function scope(){let s=Scan.spec(Number($('radius').value));$('scope').textContent=`${s.n} × ${s.n} cells · ${fmt(s.N)} possible centres across the entire universe.`;$('scanTotal').textContent=fmt(s.total);$('run').innerHTML=checkpoint&&same(checkpoint.config,settings())&&checkpoint.ordinal>0?'Resume scan <span>↗</span>':'Start scan <span>↗</span>';}
function controls(){for(let id of ['radius','duration','dt','limit','resetScan'])$(id).disabled=runActive;$('run').disabled=runActive||!db;$('pause').disabled=!runActive;$('stop').disabled=!runActive;$('pause').textContent=paused?'Resume':'Pause';}
let worker=new Worker('worker.js');
worker.onmessage=async e=>{let m=e.data;if(m.token!==token||!runActive)return;if(m.type==='error'){stop();$('status').textContent=m.message;return;}if(m.type!=='result')return;busy=true;let r=m.result;r.batch={...config,mode:'radius-scan',runId:checkpoint.runId};r.trialKey=checkpoint.runId+':'+r.initial.scan.ordinal;current=r;try{await storeRecord(r);if(!runActive||m.token!==token)return;busy=false;if(!ReplayFilter.qualifies(r)){sessionSkipped++;$('status').textContent=`Tested ${fmt(sessionDone+1)} · skipped ${fmt(sessionSkipped)} trials lasting ≤5 simulated seconds · ${fmt(sessionShown)} qualifying trials. Searching…`;if(!paused)completeTrial();return;}sessionShown++;select(r,!paused);$('status').textContent=`Animating trial ${fmt(r.initial.scan.ordinal+1)} · ${r.time.toFixed(3)} simulated seconds · ${r.outcome==='Bounded'?'bounded; no repeating orbit detected':r.outcome.toLowerCase()}. ${fmt(sessionSkipped)} short trials skipped.`;}catch(err){busy=false;if(ReplayFilter.qualifies(r))select(r,false);stop();$('status').textContent='Recording failed or storage is full. Scan stopped at this trial. Export evidence, then free space before resuming.';toast('Recording failed. The current replay is included in the latest-replays export.');}};
worker.onerror=()=>{stop();$('status').textContent='Simulation worker stopped. Resume to retry the saved trial.';};
function requestTrial(){if(!runActive||paused)return;let total=Scan.spec(config.radius).total;if(checkpoint.ordinal>=total||sessionDone>=sessionLimit){stop();$('status').textContent=checkpoint.ordinal>=total?'Enumeration complete. Every distinct triple was tested; all escapes and trials lasting >5 simulated seconds were animated.':`Session limit reached. ${fmt(sessionShown)} qualifying trials; ${fmt(sessionSkipped)} short trials skipped. Resume from the saved next trial.`;return;}busy=true;current=null;$('status').textContent=`Searching for escapes or >5 s interactions · trial ${fmt(checkpoint.ordinal+1)} of ${fmt(total)} · ${fmt(sessionSkipped)} short trials skipped…`;worker.postMessage({type:'trial',config,ordinal:checkpoint.ordinal,token});}
function completeTrial(){if(!runActive||paused||busy)return;try{checkpoint.ordinal=current.initial.scan.ordinal+1;checkpointSave();sessionDone++;$('progressBar').style.width=(checkpoint.ordinal/Scan.spec(config.radius).total*100)+'%';requestTrial();}catch(err){stop();$('status').textContent=err.message;}}
function stop(){runActive=false;paused=false;busy=false;token++;worker.postMessage({type:'stop'});controls();scope();}
$('run').onclick=()=>{for(let id of ['duration','minimum','limit'])if(!$(id).checkValidity())return $(id).reportValidity();config=settings();if(!same(checkpoint?.config,config))checkpoint={version:2,runId:(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),ordinal:0,config};if(checkpoint.ordinal>=Scan.spec(config.radius).total)return toast('This grid is complete. Restart enumeration to run it again.');sessionLimit=$('limit').value?Number($('limit').value):Infinity;sessionDone=0;sessionShown=0;sessionSkipped=0;playing=false;if(!ReplayFilter.qualifies(selected)){selected=null;render();$('clock').innerHTML='— <small>s</small>';$('outcomeBadge').textContent='SEARCHING FOR ESCAPES / >5 s';}runActive=true;paused=false;token++;try{checkpointSave();}catch(err){stop();return toast(err.message);}controls();requestTrial();};
$('pause').onclick=()=>{paused=!paused;if(paused){playing=false;$('status').textContent='Scan paused. Current trial and enumeration position preserved.';}else if(current){if(ReplayFilter.qualifies(current))select(current,true);else completeTrial();}else if(!busy)requestTrial();controls();};$('stop').onclick=()=>{stop();$('status').textContent='Stopped. Resume continues testing, displaying all escapes and interactions lasting >5 simulated seconds.';};
$('resetScan').onclick=()=>{if(runActive)return;checkpoint=null;localStorage.removeItem('three-body-radius-scan-v2');$('checkpoint').textContent='Next scan starts at the top-left. Recorded evidence is preserved.';scope();};for(let id of ['radius','duration','dt'])$(id).onchange=scope;
$('play').onclick=()=>{if(runActive){$('pause').click();return;}playing=!playing;$('play').textContent=playing?'Ⅱ':'▶';};$('restart').onclick=()=>{if(runActive){paused=true;controls();}elapsed=0;frame=0;playing=!runActive;render();};$('scrub').oninput=()=>{if(runActive){paused=true;controls();$('status').textContent='Scrubbing paused the scan. Resume replays this trial before advancing.';}playing=false;frame=Number($('scrub').value);$('play').textContent='▶';badge();render();};
new ResizeObserver(render).observe(canvas);
function logQuery(filter){let source=db.transaction('records').objectStore('records');if($('showShort').checked)return filter==='all'?{source,range:null}:{source:source.index('outcome'),range:IDBKeyRange.only(filter)};return filter==='all'?{source:source.index('eligibleId'),range:IDBKeyRange.bound([1,0],[1,Number.MAX_SAFE_INTEGER])}:{source:source.index('outcomeEligibleId'),range:IDBKeyRange.bound([filter,1,0],[filter,1,Number.MAX_SAFE_INTEGER])};}
async function counts(filter,visible=false){if(visible){let q=logQuery(filter);return req(q.source.count(q.range));}let source=db.transaction('records').objectStore('records');return req(filter==='all'?source.count():source.index('outcome').count(filter));}
async function update(){if(!db)return;let serial=++viewSerial,filter=$('filter').value;let [total,orbits,escaped,n]=await Promise.all([counts('all'),counts('Orbit candidate'),counts('Escaped'),counts(filter,true)]);if(serial!==viewSerial)return;$('total').textContent=fmt(total);$('bounded').textContent=fmt(orbits);$('escaped').textContent=fmt(escaped);$('other').textContent=fmt(total-orbits-escaped);page=Math.max(0,Math.min(page,Math.ceil(n/15)-1));let query=logQuery(filter),q=query.source.openCursor(query.range,'prev');let rows=await new Promise((resolve,reject)=>{let a=[],skip=page*15;q.onerror=()=>reject(q.error);q.onsuccess=()=>{let c=q.result;if(!c||a.length===15)return resolve(a);if(skip){let s=skip;skip=0;c.advance(s);return;}a.push(c.value);c.continue();};});if(serial!==viewSerial)return;$('rows').replaceChildren();for(let r of rows){let tr=document.createElement('tr'),cells=Array.from({length:6},()=>{let td=document.createElement('td');tr.append(td);return td;});cells[0].textContent=r.initial.scan?'Trial '+fmt(r.initial.scan.ordinal+1):'#'+r.id;let sub=document.createElement('span');sub.className='sub';sub.textContent=r.initial.v.every(v=>v===0)?'All three start at rest':'Comparison · nonzero initial velocities';cells[0].append(sub);cells[1].className='coords';for(let b=0;b<3;b++){let s=document.createElement('span'),i=document.createElement('i');i.textContent=['R','G','B'][b];s.append(i,`(${r.initial.p[2*b].toFixed(3)}, ${r.initial.p[2*b+1].toFixed(3)})`);cells[1].append(s);}let badge=document.createElement('span');badge.className='result '+(r.outcome==='Orbit candidate'?'Bounded':r.outcome);badge.textContent=r.outcome==='Bounded'?'Bounded · orbit not detected':r.outcome;let time=document.createElement('span');time.className='sub';time.textContent=r.time.toFixed(4)+' / '+r.options.duration+' s';cells[2].append(badge,time);cells[3].textContent=(r.energyError*100).toExponential(2)+'%';if(r.orbit?.detected){let period=document.createElement('span');period.className='sub';period.textContent='T ≈ '+r.orbit.period.toFixed(3)+' s · 3 cycles';cells[3].append(period);}let image=document.createElement('img');image.src=r.finalImage||thumb(r);image.alt='Final frame for recorded test '+r.id;cells[4].append(image);let button=document.createElement('button');button.textContent='↻ Replay';button.onclick=()=>{if(runActive){paused=true;controls();$('status').textContent='History replay. Resume returns to the current scan trial.';}select(r,true);canvas.scrollIntoView({behavior:'smooth',block:'center'});};cells[5].append(button);$('rows').append(tr);}$('empty').hidden=n>0;$('prev').disabled=page===0;$('next').disabled=(page+1)*15>=n;$('pageLabel').textContent=`Page ${fmt(page+1)} / ${fmt(Math.max(1,Math.ceil(n/15)))}`;}
$('filter').onchange=()=>{page=0;update();};$('showShort').onchange=()=>{page=0;update();};$('prev').onclick=()=>{page--;update();};$('next').onclick=()=>{page++;update();};
function download(data,name,type){let url=URL.createObjectURL(new Blob(Array.isArray(data)?data:[data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function collect(limit=1000,onlyOrbits=false){let source=db.transaction('records').objectStore('records'),q=onlyOrbits?source.index('outcome').openCursor(IDBKeyRange.only('Orbit candidate'),'prev'):source.openCursor(null,'prev');return new Promise((resolve,reject)=>{let a=[];q.onerror=()=>reject(q.error);q.onsuccess=()=>{let c=q.result;if(!c||a.length>=limit)return resolve(a.reverse());a.push(c.value);c.continue();};});}
async function archive(onlyOrbits=false){if(!db)return;try{let records=await collect(onlyOrbits?Infinity:1000,onlyOrbits);if(!onlyOrbits&&current&&!records.some(r=>r.trialKey===current.trialKey))records.push(current);if(!records.length)return toast(onlyOrbits?'No repeating-orbit candidates recorded.':'No trials recorded yet.');download(JSON.stringify({format:'three-body-lab-v1',checkpoint,exported:new Date().toISOString(),records}),onlyOrbits?'three-body-orbit-candidates.json':'three-body-latest-replays.json','application/json');}catch(err){toast('Export failed: '+err.message);}}
$('json').onclick=()=>archive();$('candidates').onclick=()=>archive(true);
$('csv').onclick=async()=>{if(!db)return;let pieces=['test,scan_trial,radius_m,outcome,time_s,duration_s,max_dt_s,relative_energy_error,R_x,R_y,G_x,G_y,B_x,B_y,R_vx,R_vy,G_vx,G_vy,B_vx,B_vy,period_s\r\n'];let q=db.transaction('records').objectStore('records').openCursor();await new Promise((resolve,reject)=>{q.onerror=()=>reject(q.error);q.onsuccess=()=>{let c=q.result;if(!c)return resolve();let r=c.value,a=[r.id,r.initial.scan?.ordinal!=null?r.initial.scan.ordinal+1:'',r.initial.scan?.radius||'',r.outcome,r.time,r.options.duration,r.options.dt,r.energyError,...r.initial.p,...r.initial.v,r.orbit?.period||''];pieces.push(a.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')+'\r\n');c.continue();};});download(pieces,'three-body-all-results.csv','text/csv');};
$('saveFrame').onclick=()=>{render();let a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='three-body-current-frame.png';a.click();};
$('clear').onclick=async()=>{if(runActive)return toast('Stop the scan before clearing recorded evidence.');if(!confirm('Delete all recorded trials in this browser? Export the needed evidence first. The saved scan position will remain.'))return;let tx=db.transaction('records','readwrite');tx.objectStore('records').clear();await txDone(tx);nextId=1;page=0;update();};
$('importFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;if(runActive){e.target.value='';return toast('Stop the scan before importing.');}try{if(file.size>100*1024*1024)throw Error('Archive must be smaller than 100 MB.');let data=JSON.parse(await file.text());if(data.format!=='three-body-lab-v1'||!Array.isArray(data.records)||data.records.length>5000)throw Error('Invalid archive or more than 5,000 records.');for(let r of data.records){if(!r.initial||!Array.isArray(r.initial.p)||r.initial.p.length!==6||!Array.isArray(r.initial.v)||r.initial.v.length!==6||![...r.initial.p,...r.initial.v,r.time,r.energyError,r.options?.duration,r.options?.dt].every(Number.isFinite)||!['Orbit candidate','Bounded','Escaped','Close encounter','Numerical error','Unresolved'].includes(r.outcome)||!Array.isArray(r.frames)||r.frames.length<1||r.frames.length>1500||!r.frames.every(f=>Array.isArray(f)&&f.length===7&&f.every(Number.isFinite)))throw Error('Invalid replay data.');}for(let r of data.records){delete r.id;r.finalImage=null;await storeRecord(r);}toast(data.records.length+' replay records imported. Scan checkpoint unchanged.');}catch(err){toast(err.message);}e.target.value='';};
$('methodBtn').onclick=()=>{$('method').open=true;$('method').scrollIntoView({behavior:'smooth'});};
function exitSaver(){document.body.classList.remove('screensaver');$('exitSaver').hidden=true;if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});render();}
$('saver').onclick=()=>{document.body.classList.add('screensaver');$('exitSaver').hidden=false;document.documentElement.requestFullscreen?.().catch(()=>{});render();};$('exitSaver').onclick=exitSaver;document.addEventListener('keydown',e=>{if(e.key==='Escape')exitSaver();});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){document.body.classList.remove('screensaver');$('exitSaver').hidden=true;}});
async function init(){try{let saved=JSON.parse(localStorage.getItem('three-body-radius-scan-v2')||'null');if(saved?.version===2&&Number.isSafeInteger(saved.ordinal)&&saved.ordinal>=0&&saved.ordinal<=Scan.spec(saved.config.radius).total&&Number.isFinite(saved.config.duration)&&saved.config.duration>=1&&saved.config.duration<=300&&[.002,.001,.0005].includes(saved.config.dt)){checkpoint=saved;$('radius').value=String(saved.config.radius);$('duration').value=Math.max(6,saved.config.duration);$('dt').value=String(saved.config.dt);}}catch{}scope();showCheckpoint();selected=null;render();$('clock').innerHTML='— <small>s</small>';$('outcomeBadge').textContent='WAITING FOR ESCAPE / >5 s TRIAL';requestAnimationFrame(animate);try{let open=indexedDB.open('three-body-lab',4);open.onupgradeneeded=()=>{let d=open.result,store=d.objectStoreNames.contains('records')?open.transaction.objectStore('records'):d.createObjectStore('records',{keyPath:'id'});if(!store.indexNames.contains('outcome'))store.createIndex('outcome','outcome');if(!store.indexNames.contains('trialKey'))store.createIndex('trialKey','trialKey',{unique:true});if(!store.indexNames.contains('eligibleId'))store.createIndex('eligibleId',['displayEligible','id']);if(!store.indexNames.contains('outcomeEligibleId'))store.createIndex('outcomeEligibleId',['outcome','displayEligible','id']);let migrate=store.openCursor();migrate.onsuccess=()=>{let c=migrate.result;if(!c)return;let r=c.value;r.displayEligible=Number(ReplayFilter.qualifies(r));c.update(r);c.continue();};};db=await req(open);db.onversionchange=()=>{db.close();stop();toast('Reload this tab to continue with the updated database.');};let cursor=await req(db.transaction('records').objectStore('records').openCursor(null,'prev'));nextId=cursor?cursor.key+1:1;await update();$('status').textContent='Ready. All escaped outcomes and trials lasting more than 5 simulated seconds will be animated.';controls();}catch(err){$('status').textContent='Persistent recording is unavailable. Enable browser storage and reload before starting the scan.';toast(err.message);}}
init();
